CREATE OR REPLACE FUNCTION public.people_week_sent(t uuid,e uuid,first_day date,last_day date) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.hr_shifts WHERE tenant_id=t AND employee_id=e AND shift_date BETWEEN first_day AND last_day) AND NOT EXISTS(SELECT 1 FROM public.hr_shifts s WHERE s.tenant_id=t AND s.employee_id=e AND s.shift_date BETWEEN first_day AND last_day AND NOT EXISTS(SELECT 1 FROM public.hr_rota_weeks w WHERE w.tenant_id=t AND w.venue_id=COALESCE(s.venue_id,(SELECT venue_id FROM public.hr_employees WHERE id=e AND tenant_id=t)) AND w.week_start=date_trunc('week',s.shift_date)::date AND w.status='sent')); $$;
REVOKE ALL ON FUNCTION public.people_week_sent(uuid,uuid,date,date) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.people_work_period(uuid,uuid,date,date)'::regprocedure) INTO definition; definition:=replace(definition,'''fingerprint'',f,','''ready'',public.people_week_sent(t,e,first_day,last_day),''fingerprint'',f,'); definition:=replace(definition,'WHEN now()>=deadline THEN ''manager_record''','WHEN NOT public.people_week_sent(t,e,first_day,last_day) THEN ''waiting_for_rotas'' WHEN now()>=deadline THEN ''manager_record'''); EXECUTE definition;
SELECT pg_get_functiondef('public.rota_confirm_my_work(uuid,date,date,text,text,text)'::regprocedure) INTO definition; definition:=replace(definition,'PERFORM pg_advisory_xact_lock','IF last_day-first_day=6 AND NOT public.people_week_sent(t,e,first_day,last_day) THEN RAISE EXCEPTION ''Every venue in your week must send its rota first'';END IF;PERFORM pg_advisory_xact_lock'); EXECUTE definition; END $$;
REVOKE ALL ON FUNCTION public.people_work_period(uuid,uuid,date,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.people_work_period(uuid,uuid,date,date) TO authenticated;
REVOKE ALL ON FUNCTION public.rota_confirm_my_work(uuid,date,date,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rota_confirm_my_work(uuid,date,date,text,text,text) TO authenticated;